HelpResource _stateCatalogEntry({
  required String id, required String title, required String description,
  required List<String> needs, required List<String> states,
  required String url, required String area, required String provider,
  required String scope, required String eligibility,
  required String application, required String cost,
  List<String> extraSources = const <String>[],
}) => HelpResource(
  id: id, title: title, description: description, needs: needs,
  states: states, url: url, serviceArea: area, providerType: provider,
  serviceScope: scope, eligibility: eligibility, howToApply: application,
  cost: cost, label: provider + ' • ' + scope,
  reviewedAt: '2026-11-05', verified: '',
  sourceUrls: [url, ...extraSources],
);

